#!/usr/bin/env python3
"""Create one .m3u playlist per album in a music library.

An album is any folder that directly contains audio files, or a folder
whose CD1/CD2/Disc 1/... subfolders contain the audio (a multi-disc album).
A multi-disc album gets one playlist in the album folder that lists every
disc in order (CD1/1. Song.flac, CD2/1. Song.flac, ...). Artist folders,
empty folders, and junk directories (no tracks) are skipped.

Playlists are written as UTF-8 with an #EXTM3U header and a
"# generated by album-m3u" marker line, using paths relative to the
album folder so they survive remounts.

Only playlists this tool generated are ever replaced or deleted: files
with the marker, and plain playlists from older versions of this tool
(named after their folder, listing only that folder's audio files in
order). Hand-made playlists are never touched.

Modes:
  rebuild   Delete generated playlists, then create a playlist for every
            album. Use this for the first run or a full refresh.
  update    Create playlists for albums that do not have one, replace
            generated playlists that are out of date (renamed or added
            tracks, renamed album folder), and remove superseded
            per-disc playlists. Use this when you add or retag albums.

Examples:
  album-m3u rebuild --dry-run --root /path/to/library
  album-m3u rebuild --root /path/to/library
  album-m3u update            (uses $DEFAULT_MUSIC)
"""

from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from mm_common import (  # noqa: E402
    album_playlist_tracks,
    audio_in,
    disc_dirs_with_audio,
    generated_playlists_for_album,
    is_generated_playlist,
    is_playlist,
    looks_like_stale_legacy,
    playlist_is_current,
    playlist_path,
    playlists_in,
    render_playlist,
    unrepresentable,
    write_playlist_file,
)

# No built-in library path: the root comes from --root or $DEFAULT_MUSIC.
_env_music = os.getenv("DEFAULT_MUSIC", "").strip()
DEFAULT_ROOT: Path | None = Path(_env_music).expanduser() if _env_music else None

# Directories we never treat as albums, even if they somehow have audio.
SKIP_DIR_NAMES = {".git", ".trash", ".trashes", "@eadir"}


def should_skip_dir(path: Path) -> bool:
    return path.name.startswith(".") or path.name.lower() in SKIP_DIR_NAMES


def find_playlists(root: Path) -> list[Path]:
    found: list[Path] = []
    for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
        dirnames[:] = [d for d in dirnames if not should_skip_dir(Path(dirpath) / d)]
        for name in filenames:
            path = Path(dirpath) / name
            if is_playlist(path):
                found.append(path)
    found.sort(key=lambda p: str(p).casefold())
    return found


def find_albums(root: Path) -> list[tuple[Path, list[Path]]]:
    """Every album folder under root (not root itself) with its tracks.

    A folder with no audio of its own but with CD1/CD2/... subfolders that
    hold audio is one multi-disc album; its disc folders are not albums.
    """
    albums: list[tuple[Path, list[Path]]] = []
    for dirpath, dirnames, _filenames in os.walk(root, followlinks=False):
        current = Path(dirpath)
        dirnames[:] = [d for d in dirnames if not should_skip_dir(current / d)]
        if current == root or should_skip_dir(current):
            continue
        here = audio_in(current)
        if here:
            albums.append((current, here))
            continue
        discs = disc_dirs_with_audio(current)
        if discs:
            albums.append((current, album_playlist_tracks(current)))
            disc_names = {d.name for d in discs}
            dirnames[:] = [d for d in dirnames if d not in disc_names]
    albums.sort(key=lambda item: str(item[0]).casefold())
    return albums


def write_playlist(dest: Path, tracks: list[Path], dry_run: bool) -> None:
    """Write relative paths so playlists survive remounts."""
    for bad in unrepresentable(dest.parent, tracks):
        print(f"warning: file name contains a line break, left out of playlist: {bad}", file=sys.stderr)
    if dry_run:
        return
    write_playlist_file(dest, render_playlist(dest.parent, tracks))


def _delete(path: Path, dry_run: bool) -> bool:
    if dry_run:
        return True
    try:
        path.unlink()
        return True
    except OSError as exc:
        print(f"warning: could not delete {path}: {exc}", file=sys.stderr)
        return False


def _report_kept(path: Path) -> None:
    if looks_like_stale_legacy(path):
        print(f"keep    {path}  (hand-made or stale: lists files that no longer exist; review it)")


def cmd_rebuild(root: Path, dry_run: bool) -> int:
    playlists = find_playlists(root)
    albums = find_albums(root)

    deleted = kept = 0
    for playlist in playlists:
        if not is_generated_playlist(playlist):
            kept += 1
            _report_kept(playlist)
            continue
        print(f"delete  {playlist}")
        if _delete(playlist, dry_run):
            deleted += 1

    created = blocked = 0
    for album_dir, tracks in albums:
        dest = playlist_path(album_dir)
        if dest.exists() and not is_generated_playlist(dest):
            print(f"skip    {dest}  (hand-made playlist with this name; not overwritten)")
            blocked += 1
            continue
        print(f"create  {dest}  ({len(tracks)} tracks)")
        write_playlist(dest, tracks, dry_run)
        created += 1

    prefix = "dry-run: would " if dry_run else ""
    print(
        f"\n{prefix}delete {deleted} generated playlist(s), "
        f"create {created} album playlist(s); "
        f"kept {kept} hand-made playlist(s)"
        + (f", {blocked} album(s) skipped because a hand-made playlist has the name" if blocked else "")
    )
    return 0


def cmd_update(root: Path, dry_run: bool) -> int:
    albums = find_albums(root)
    created = replaced = removed = skipped = blocked = 0

    for album_dir, tracks in albums:
        dest = playlist_path(album_dir)

        # Generated playlists that are not the album's canonical one are
        # stale: per-disc playlists from older versions, or a playlist
        # named after the folder's previous name.
        for old in generated_playlists_for_album(album_dir):
            if old == dest:
                continue
            print(f"remove  {old}  (superseded generated playlist)")
            if _delete(old, dry_run):
                removed += 1
        for other in playlists_in(album_dir):
            if other != dest and not is_generated_playlist(other):
                _report_kept(other)

        if dest.exists():
            if not is_generated_playlist(dest):
                blocked += 1
                _report_kept(dest)
                continue
            if playlist_is_current(dest, album_dir, tracks):
                skipped += 1
                continue
            # A legacy (headerless) playlist that still lists exactly the
            # current tracks is up to date; leave it for rebuild to upgrade.
            if _legacy_matches(dest, tracks):
                skipped += 1
                continue
            print(f"replace {dest}  ({len(tracks)} tracks, was out of date)")
            write_playlist(dest, tracks, dry_run)
            replaced += 1
            continue

        print(f"create  {dest}  ({len(tracks)} tracks)")
        write_playlist(dest, tracks, dry_run)
        created += 1

    prefix = "dry-run: would " if dry_run else ""
    print(
        f"\n{prefix}create {created} new album playlist(s), "
        f"replace {replaced} out-of-date generated playlist(s), "
        f"remove {removed} superseded playlist(s), "
        f"skip {skipped} album(s) that already have a current one"
        + (f", leave {blocked} hand-made playlist(s) alone" if blocked else "")
    )
    return 0


def _legacy_matches(path: Path, tracks: list[Path]) -> bool:
    try:
        lines = path.read_bytes().decode("utf-8", "surrogateescape").splitlines()
    except OSError:
        return False
    entries = [line.strip() for line in lines if line.strip()]
    if any(entry.startswith("#") for entry in entries):
        return False
    return entries == [t.relative_to(path.parent).as_posix() for t in tracks]


def parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Create a .m3u playlist for each album folder."
    )
    parser.add_argument(
        "mode",
        choices=("rebuild", "update"),
        help="rebuild = delete generated playlists and recreate all; "
        "update = create missing and refresh out-of-date generated playlists",
    )
    parser.add_argument(
        "--root",
        type=Path,
        default=None,
        help="library root (default: $DEFAULT_MUSIC; required when that is unset)",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="print what would happen without writing or deleting files",
    )
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    chosen = args.root or DEFAULT_ROOT
    if chosen is None:
        print("error: no library root. Pass --root DIR, or set DEFAULT_MUSIC.", file=sys.stderr)
        return 2
    root = chosen.expanduser().resolve()

    if not root.is_dir():
        print(f"error: library not found: {root}", file=sys.stderr)
        print("Is the drive mounted?", file=sys.stderr)
        return 1

    if args.mode == "rebuild":
        return cmd_rebuild(root, args.dry_run)
    return cmd_update(root, args.dry_run)


if __name__ == "__main__":
    sys.exit(main())
